import "dotenv/config";

function localSafeErr(err) {
  return err?.response?.data?.error?.message || err?.response?.data?.message || err?.message || String(err);
}

process.on("unhandledRejection", (err) => {
  console.error("[process] unhandledRejection", { error: localSafeErr(err) });
});

process.on("uncaughtException", (err) => {
  console.error("[process] uncaughtException", { error: localSafeErr(err) });
  process.exit(1);
});

async function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function startPolling(bot, log, safeErr) {
  const { run } = await import("@grammyjs/runner");
  let backoff = 2000;
  let handle = null;
  while (true) {
    try {
      log.info("Telegram polling clear webhook", { dropPendingUpdates: true });
      await bot.api.deleteWebhook({ drop_pending_updates: true });
      log.info("Telegram polling started", { concurrency: 1 });
      handle = run(bot);
      await handle.task();
      log.warn("Telegram polling stopped", {});
      backoff = 2000;
    } catch (err) {
      const message = safeErr(err);
      log.error("Telegram polling failed", { error: message, retryMs: backoff });
      if (handle) {
        try { await handle.stop(); } catch {}
        handle = null;
      }
      await sleep(backoff);
      backoff = Math.min(20000, backoff === 2000 ? 5000 : backoff * 2);
    }
  }
}

async function boot() {
  try {
    console.log("[boot] start");
    const { cfg, logEnvSanity } = await import("./lib/config.js");
    const { log, safeErr } = await import("./lib/log.js");
    const { connectDb, closeDb } = await import("./lib/db.js");
    const { createBot } = await import("./bot.js");
    const { startSnipePolling, stopSnipePolling } = await import("./services/snipes.js");

    logEnvSanity();
    if (!cfg.TELEGRAM_BOT_TOKEN) {
      console.error("TELEGRAM_BOT_TOKEN is required. Add it in the Config tab and redeploy.");
      process.exit(1);
    }

    await connectDb();
    const bot = await createBot(cfg.TELEGRAM_BOT_TOKEN);
    await bot.init();
    await bot.api.setMyCommands([
      { command: "start", description: "Open the trading menu" },
      { command: "help", description: "How to use the bot" },
      { command: "wallet", description: "Create, import, view, or disconnect wallet" },
      { command: "buy", description: "Preview and confirm a buy" },
      { command: "sell", description: "Preview and confirm a sell" },
      { command: "snipe", description: "Create a snipe target" },
      { command: "balance", description: "Show wallet balances" },
      { command: "positions", description: "Show open positions" },
      { command: "settings", description: "Edit trading defaults" }
    ]);

    startSnipePolling(bot);
    process.once("SIGTERM", async () => { stopSnipePolling(); await closeDb(); process.exit(0); });
    process.once("SIGINT", async () => { stopSnipePolling(); await closeDb(); process.exit(0); });
    await startPolling(bot, log, safeErr);
  } catch (err) {
    console.error("Boot error", { code: err?.code, error: localSafeErr(err) });
    if (err?.code === "ERR_MODULE_NOT_FOUND") console.error("Check package dependencies and relative .js imports.");
    process.exit(1);
  }
}

boot();

crypto.js.content:
import crypto from "node:crypto";
import { cfg } from "./config.js";

function key() {
  if (!cfg.WALLET_ENCRYPTION_SECRET) throw new Error("WALLET_ENCRYPTION_SECRET missing");
  return crypto.createHash("sha256").update(cfg.WALLET_ENCRYPTION_SECRET).digest();
}

export function encryptSecret(payload) {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv("aes-256-gcm", key(), iv);
  const ciphertext = Buffer.concat([cipher.update(JSON.stringify(payload), "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return {
    alg: "aes-256-gcm",
    iv: iv.toString("base64"),
    tag: tag.toString("base64"),
    data: ciphertext.toString("base64")
  };
}

db.js.content:
import { MongoClient } from "mongodb";
import { cfg } from "./config.js";
import { log, safeErr } from "./log.js";

let client = null;
let db = null;

export async function connectDb() {
  if (!cfg.MONGODB_URI) {
    log.warn("MongoDB disabled", { collection: "all", operation: "connect", reason: "MONGODB_URI missing" });
    return null;
  }
  if (db) return db;
  try {
    client = new MongoClient(cfg.MONGODB_URI, { maxPoolSize: 8, ignoreUndefined: true });
    await client.connect();
    db = client.db();
    await ensureIndexes();
    log.info("MongoDB connected", { collection: "all", operation: "connect" });
    return db;
  } catch (err) {
    log.error("MongoDB connection failed", { collection: "all", operation: "connect", error: safeErr(err) });
    return null;
  }
}

export function getDb() {
  return db;
}

export async function col(name) {
  const active = db || await connectDb();
  return active ? active.collection(name) : null;
}

export async function ensureIndexes() {
  if (!db) return;
  const indexes = [
    ["users", { telegramUserId: 1 }, { unique: true }],
    ["wallets", { userId: 1, status: 1 }, {}],
    ["snipes", { status: 1, updatedAt: -1 }, {}],
    ["trades", { userId: 1, createdAt: -1 }, {}],
    ["positions", { userId: 1, status: 1 }, {}]
  ];
  for (const [name, key, options] of indexes) {
    try {
      await db.collection(name).createIndex(key, options);
    } catch (err) {
      log.error("MongoDB index failed", { collection: name, operation: "createIndex", error: safeErr(err) });
    }
  }
}

export async function closeDb() {
  if (client) await client.close();
  client = null;
  db = null;
}

export function cleanMutable(obj = {}) {
  const out = { ...obj };
  delete out._id;
  delete out.createdAt;
  return out;
}

log.js.content:
export function safeErr(err) {
  return err?.response?.data?.error?.message || err?.response?.data?.message || err?.message || String(err);
}

export const log = {
  info(message, meta = {}) {
    console.log(JSON.stringify({ level: "info", message, ...meta }));
  },
  warn(message, meta = {}) {
    console.warn(JSON.stringify({ level: "warn", message, ...meta }));
  },
  error(message, meta = {}) {
    console.error(JSON.stringify({ level: "error", message, ...meta }));
  }
};

export function publicUser(ctx) {
  return {
    userId: ctx?.from?.id ? String(ctx.from.id) : "unknown",
    chatId: ctx?.chat?.id ? String(ctx.chat.id) : "unknown"
  };
}

