import { col } from "../lib/db.js";
import { log, safeErr } from "../lib/log.js";

const memoryPositions = new Map();
const key = (userId, tokenAddress) => `${userId}:${tokenAddress.toLowerCase()}`;

export async function listPositions(userId) {
  const positions = await col("positions");
  if (!positions) return [...memoryPositions.values()].filter((p) => p.userId === String(userId) && p.status === "open");
  try {
    return await positions.find({ userId: String(userId), status: "open" }).sort({ updatedAt: -1 }).limit(20).toArray();
  } catch (err) {
    log.error("Positions read failed", { collection: "positions", operation: "find", userId: String(userId), error: safeErr(err) });
    return [];
  }
}

export async function upsertPositionFromTrade({ userId, tokenAddress, side, amount, estimatedValue }) {
  const now = new Date();
  const sizeDelta = side === "buy" ? Number(amount || 0) : -Number(amount || 0);
  const positions = await col("positions");
  if (!positions) {
    const id = key(String(userId), tokenAddress);
    const existing = memoryPositions.get(id) || { userId: String(userId), tokenAddress, size: 0, costBasis: 0, realizedPnl: 0, averageEntryPrice: 0, status: "open", createdAt: now };
    existing.size = Math.max(0, Number(existing.size || 0) + sizeDelta);
    existing.costBasis = Math.max(0, Number(existing.costBasis || 0) + (side === "buy" ? Number(estimatedValue || 0) : 0));
    existing.averageEntryPrice = existing.size > 0 ? existing.costBasis / existing.size : 0;
    existing.status = existing.size > 0 ? "open" : "closed";
    existing.updatedAt = now;
    memoryPositions.set(id, existing);
    return existing;
  }
  try {
    await positions.updateOne(
      { userId: String(userId), tokenAddress: tokenAddress.toLowerCase() },
      {
        $setOnInsert: { createdAt: now, realizedPnl: 0, costBasis: 0 },
        $inc: { size: sizeDelta, ...(side === "buy" ? { costBasis: Number(estimatedValue || 0) } : {}) },
        $set: { userId: String(userId), tokenAddress: tokenAddress.toLowerCase(), status: "open", updatedAt: now }
      },
      { upsert: true }
    );
    const pos = await positions.findOne({ userId: String(userId), tokenAddress: tokenAddress.toLowerCase() });
    const avg = Number(pos?.size || 0) > 0 ? Number(pos?.costBasis || 0) / Number(pos.size) : 0;
    await positions.updateOne({ _id: pos._id }, { $set: { averageEntryPrice: avg, updatedAt: new Date() } });
    return await positions.findOne({ _id: pos._id });
  } catch (err) {
    log.error("Position update failed", { collection: "positions", operation: "updateOne", userId: String(userId), error: safeErr(err) });
    throw err;
  }
}

snipes.js.content:
import { cfg } from "../lib/config.js";
import { col } from "../lib/db.js";
import { log, safeErr } from "../lib/log.js";
import { buildTradePreview, executeTrade } from "./trading.js";

const memorySnipes = new Map();
let polling = false;
let lastMemLog = 0;

export async function saveSnipe(userId, data) {
  const now = new Date();
  const snipeId = data.snipeId || `${userId}:${String(data.tokenAddress).toLowerCase()}`;
  const doc = {
    snipeId,
    userId: String(userId),
    tokenAddress: String(data.tokenAddress).toLowerCase(),
    amount: Number(data.amount),
    slippage: Number(data.slippage),
    maxBuy: Number(data.maxBuy),
    priorityFee: Number(data.priorityFee || 0),
    takeProfit: Number(data.takeProfit || 0),
    stopLoss: Number(data.stopLoss || 0),
    status: data.status || "active",
    lastCheckData: data.lastCheckData || null,
    updatedAt: now
  };
  const snipes = await col("snipes");
  if (!snipes) {
    memorySnipes.set(snipeId, { ...doc, createdAt: now });
    return memorySnipes.get(snipeId);
  }
  try {
    await snipes.updateOne({ snipeId }, { $setOnInsert: { createdAt: now }, $set: doc }, { upsert: true });
    return await snipes.findOne({ snipeId });
  } catch (err) {
    log.error("Snipe write failed", { collection: "snipes", operation: "updateOne", userId: String(userId), error: safeErr(err) });
    throw err;
  }
}

export async function listSnipes(userId, activeOnly = false) {
  const snipes = await col("snipes");
  if (!snipes) return [...memorySnipes.values()].filter((s) => s.userId === String(userId) && (!activeOnly || s.status === "active"));
  try {
    return await snipes.find({ userId: String(userId), ...(activeOnly ? { status: "active" } : {}) }).sort({ updatedAt: -1 }).limit(20).toArray();
  } catch (err) {
    log.error("Snipe read failed", { collection: "snipes", operation: "find", userId: String(userId), error: safeErr(err) });
    return [];
  }
}

async function getActiveSnipes() {
  const snipes = await col("snipes");
  if (!snipes) return [...memorySnipes.values()].filter((s) => s.status === "active");
  return snipes.find({ status: "active" }).limit(25).toArray();
}

async function markSnipe(snipeId, patch) {
  const snipes = await col("snipes");
  const now = new Date();
  if (!snipes) {
    const s = memorySnipes.get(snipeId);
    if (s) memorySnipes.set(snipeId, { ...s, ...patch, updatedAt: now });
    return;
  }
  await snipes.updateOne({ snipeId }, { $set: { ...patch, updatedAt: now } });
}

async function runCycle(bot) {
  const active = await getActiveSnipes();
  log.info("Snipe poll cycle", { count: active.length });
  for (const snipe of active) {
    try {
      const preview = await buildTradePreview({ userId: snipe.userId, side: "buy", tokenAddress: snipe.tokenAddress, amount: snipe.amount, slippage: snipe.slippage });
      await markSnipe(snipe.snipeId, { lastCheckData: { ok: preview.ok, warnings: preview.warnings || [], checkedAt: new Date() } });
      if (!preview.ok || preview.requiresExtraConfirm || !cfg.TRADING_ENABLED) continue;
      const result = await executeTrade(preview);
      await markSnipe(snipe.snipeId, { status: result.ok ? "executed" : "failed", lastCheckData: { result, checkedAt: new Date() } });
      await bot.api.sendMessage(snipe.userId, result.ok ? `Snipe executed. ${result.message}` : `Snipe failed. ${result.message}`);
    } catch (err) {
      log.error("Snipe poll item failed", { snipeId: snipe.snipeId, error: safeErr(err) });
    }
  }
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function startSnipePolling(bot) {
  if (polling) return;
  polling = true;
  log.info("Snipe polling started", { intervalMs: cfg.SNIPE_POLL_INTERVAL_MS });
  void (async () => {
    while (polling) {
      try {
        await runCycle(bot);
      } catch (err) {
        log.error("Snipe poll cycle failed", { error: safeErr(err) });
      }
      const now = Date.now();
      if (now - lastMemLog > 60000) {
        const m = process.memoryUsage();
        log.info("Memory", { rssMB: Math.round(m.rss / 1e6), heapUsedMB: Math.round(m.heapUsed / 1e6) });
        lastMemLog = now;
      }
      await sleep(Math.max(5000, Number(cfg.SNIPE_POLL_INTERVAL_MS || 15000)));
    }
  })();
}

export function stopSnipePolling() {
  polling = false;
}

trading.js.content:
import crypto from "node:crypto";
import { cfg } from "../lib/config.js";
import { col } from "../lib/db.js";
import { log, safeErr } from "../lib/log.js";
import { getSettings } from "./users.js";
import { getWallet } from "./wallets.js";
import { fetchLiquidity, fetchQuote, fetchRisk, validateTokenAddress } from "./market.js";
import { upsertPositionFromTrade } from "./positions.js";

const memoryTrades = new Map();

export async function buildTradePreview({ userId, side, tokenAddress, amount, slippage }) {
  const token = validateTokenAddress(tokenAddress);
  if (!token) return { ok: false, message: "That token address looks invalid." };
  const numericAmount = Number(amount);
  if (!Number.isFinite(numericAmount) || numericAmount <= 0) return { ok: false, message: "Enter a valid amount." };
  const wallet = await getWallet(userId);
  if (!wallet) return { ok: false, message: "Set up Wallet first.", needsWallet: true };
  const settings = await getSettings(userId);
  const usedSlippage = slippage === undefined || slippage === "" ? Number(settings.defaultSlippage) : Number(slippage);
  if (!Number.isFinite(usedSlippage) || usedSlippage < 0 || usedSlippage > 50) return { ok: false, message: "Slippage must be between 0 and 50%." };

  const warnings = [];
  const quote = await fetchQuote({ side, tokenAddress: token, amount: numericAmount, slippage: usedSlippage, userId });
  if (!quote.ok) warnings.push(...(quote.warnings || ["Quote unavailable."]));

  const liquidity = await fetchLiquidity(token);
  if (liquidity.warning) warnings.push(liquidity.warning);
  const liqValue = Number(liquidity.data?.liquidityUsd || liquidity.data?.usd || 0);
  if (liquidity.ok && liqValue > 0 && liqValue < numericAmount * 1000) warnings.push("Low liquidity warning.");

  const risk = await fetchRisk(token);
  if (risk.warning) warnings.push(risk.warning);
  const riskLevel = String(risk.data?.level || risk.data?.severity || "").toLowerCase();
  if (["high", "critical", "risky"].includes(riskLevel)) warnings.push("Risky-token warning from configured risk API.");

  if (side === "buy" && numericAmount > Number(settings.maxBuy || 0)) warnings.push("Trade exceeds your max buy setting.");
  const requiresExtraConfirm = warnings.length > 0 || !quote.ok || numericAmount > Number(settings.maxBuy || 0);
  return { ok: true, side, tokenAddress: token, amount: numericAmount, slippage: usedSlippage, wallet, settings, quote, liquidity, risk, warnings, requiresExtraConfirm };
}

export function formatPreview(preview) {
  const q = preview.quote?.data || {};
  const out = q.expectedOut || q.amountOut || q.toAmount || "quote unavailable";
  const fee = q.fee || q.estimatedFee || "estimated";
  const warn = preview.warnings.length ? `\nWarnings: ${preview.warnings.join(" ")}` : "";
  const mode = cfg.TRADING_ENABLED ? "Trading is enabled." : "Preview only. Trading is disabled.";
  return `${preview.side.toUpperCase()} preview\nToken: ${preview.tokenAddress}\nAmount: ${preview.amount} ${cfg.NATIVE_SYMBOL}\nExpected: ${out}\nSlippage: ${preview.slippage}%\nFees: ${fee}\n${mode}${warn}\nCrypto trading is high risk. Not financial advice.`;
}

export async function executeTrade(preview) {
  const now = new Date();
  const tradeId = crypto.randomUUID();
  const baseDoc = {
    tradeId,
    userId: String(preview.wallet.userId),
    side: preview.side,
    tokenAddress: preview.tokenAddress.toLowerCase(),
    amountIn: preview.amount,
    quoteData: preview.quote?.data || null,
    txHash: "",
    status: cfg.TRADING_ENABLED ? "created" : "preview_only",
    errorSummary: "",
    updatedAt: now
  };
  const trades = await col("trades");
  if (!trades) memoryTrades.set(tradeId, { ...baseDoc, createdAt: now });
  else {
    try {
      await trades.updateOne({ tradeId }, { $setOnInsert: { createdAt: now }, $set: baseDoc }, { upsert: true });
    } catch (err) {
      log.error("Trade write failed", { collection: "trades", operation: "updateOne", tradeId, error: safeErr(err) });
      throw err;
    }
  }

  if (!cfg.TRADING_ENABLED) return { ok: true, status: "preview_only", message: "Preview saved. Trading is disabled." };
  if (!cfg.DEX_AGGREGATOR_BASE_URL) return { ok: false, message: "Execution service is not configured." };

  log.info("Trading gateway call start", { feature: "execute", side: preview.side, tokenAddress: preview.tokenAddress, userId: String(preview.wallet.userId), tradeId });
  try {
    const response = await fetch(`${cfg.DEX_AGGREGATOR_BASE_URL}/execute`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(cfg.DEX_AGGREGATOR_API_KEY ? { Authorization: `Bearer ${cfg.DEX_AGGREGATOR_API_KEY}` } : {})
      },
      body: JSON.stringify({ chainId: cfg.CHAIN_ID, tradeId, side: preview.side, tokenAddress: preview.tokenAddress, amount: preview.amount, slippage: preview.slippage, walletAddress: preview.wallet.publicAddress })
    });
    const text = await response.text();
    let json = null;
    try { json = JSON.parse(text); } catch {}
    if (!response.ok) throw new Error(json?.message || text || "Execution failed");
    const txHash = json?.txHash || json?.transactionHash || "submitted";
    const status = txHash === "submitted" ? "submitted" : "submitted";
    if (trades) await trades.updateOne({ tradeId }, { $set: { txHash, status, updatedAt: new Date() } });
    await upsertPositionFromTrade({ userId: preview.wallet.userId, tokenAddress: preview.tokenAddress, side: preview.side, amount: preview.amount, estimatedValue: preview.amount });
    log.info("Trading gateway call success", { feature: "execute", side: preview.side, tokenAddress: preview.tokenAddress, userId: String(preview.wallet.userId), tradeId });
    return { ok: true, status, txHash, message: `Submitted. Tx: ${txHash}` };
  } catch (err) {
    const errorSummary = safeErr(err);
    if (trades) await trades.updateOne({ tradeId }, { $set: { status: "failed", errorSummary, updatedAt: new Date() } });
    log.error("Trading gateway call failed", { feature: "execute", side: preview.side, tokenAddress: preview.tokenAddress, userId: String(preview.wallet.userId), tradeId, error: errorSummary });
    return { ok: false, message: "Transaction failed before submission. Check settings and try again." };
  }
}

users.js.content:
import { col, cleanMutable } from "../lib/db.js";
import { log, safeErr } from "../lib/log.js";

const memoryUsers = new Map();

export const defaultSettings = {
  defaultAmount: 0.01,
  defaultSlippage: 1,
  maxBuy: 0.05,
  maxPercentPerTrade: 10,
  priorityFee: 0,
  takeProfit: 0,
  stopLoss: 0,
  confirmations: true
};

function userIdFromCtx(ctx) {
  return String(ctx.from?.id || ctx.chat?.id || "unknown");
}

export async function ensureUser(ctx) {
  const userId = userIdFromCtx(ctx);
  const now = new Date();
  const mutable = cleanMutable({
    telegramUserId: userId,
    username: ctx.from?.username || "",
    firstName: ctx.from?.first_name || "",
    lastName: ctx.from?.last_name || "",
    updatedAt: now
  });
  const users = await col("users");
  if (!users) {
    const existing = memoryUsers.get(userId) || { telegramUserId: userId, settings: { ...defaultSettings }, createdAt: now };
    const next = { ...existing, ...mutable, settings: existing.settings || { ...defaultSettings } };
    memoryUsers.set(userId, next);
    return next;
  }
  try {
    await users.updateOne(
      { telegramUserId: userId },
      { $setOnInsert: { createdAt: now, settings: { ...defaultSettings } }, $set: mutable },
      { upsert: true }
    );
    return await users.findOne({ telegramUserId: userId });
  } catch (err) {
    log.error("User upsert failed", { collection: "users", operation: "updateOne", userId, error: safeErr(err) });
    return { telegramUserId: userId, settings: { ...defaultSettings } };
  }
}

export async function getSettings(userId) {
  const users = await col("users");
  if (!users) return memoryUsers.get(String(userId))?.settings || { ...defaultSettings };
  try {
    const user = await users.findOne({ telegramUserId: String(userId) });
    return { ...defaultSettings, ...(user?.settings || {}) };
  } catch (err) {
    log.error("Settings read failed", { collection: "users", operation: "findOne", userId: String(userId), error: safeErr(err) });
    return { ...defaultSettings };
  }
}

export async function updateSetting(userId, key, value) {
  const allowed = Object.keys(defaultSettings);
  if (!allowed.includes(key)) throw new Error("Unsupported setting");
  const now = new Date();
  const users = await col("users");
  if (!users) {
    const user = memoryUsers.get(String(userId)) || { telegramUserId: String(userId), settings: { ...defaultSettings }, createdAt: now };
    user.settings = { ...defaultSettings, ...user.settings, [key]: value };
    user.updatedAt = now;
    memoryUsers.set(String(userId), user);
    return user.settings;
  }
  try {
    await users.updateOne(
      { telegramUserId: String(userId) },
      { $setOnInsert: { createdAt: now }, $set: { [`settings.${key}`]: value, updatedAt: now } },
      { upsert: true }
    );
    return getSettings(userId);
  } catch (err) {
    log.error("Settings update failed", { collection: "users", operation: "updateOne", userId: String(userId), error: safeErr(err) });
    throw err;
  }
}

wallets.js.content:
import { Wallet } from "ethers";
import { cfg } from "../lib/config.js";
import { encryptSecret } from "../lib/crypto.js";
import { col } from "../lib/db.js";
import { log, safeErr } from "../lib/log.js";

const memoryWallets = new Map();

export async function getWallet(userId) {
  const wallets = await col("wallets");
  if (!wallets) return memoryWallets.get(String(userId)) || null;
  try {
    return await wallets.findOne({ userId: String(userId), status: "active" });
  } catch (err) {
    log.error("Wallet read failed", { collection: "wallets", operation: "findOne", userId: String(userId), error: safeErr(err) });
    return null;
  }
}

async function saveWallet(userId, publicAddress, encryptedSecretPayload, walletType) {
  const now = new Date();
  const doc = { userId: String(userId), publicAddress, encryptedSecretPayload, walletType, status: "active", updatedAt: now };
  const wallets = await col("wallets");
  if (!wallets) {
    const inMem = { ...doc, createdAt: now };
    memoryWallets.set(String(userId), inMem);
    return inMem;
  }
  try {
    await wallets.updateMany({ userId: String(userId), status: "active" }, { $set: { status: "archived", updatedAt: now } });
    await wallets.updateOne(
      { userId: String(userId), publicAddress },
      { $setOnInsert: { }, $set: doc },
      { upsert: true }
    );
    return await getWallet(userId);
  } catch (err) {
    log.error("Wallet write failed", { collection: "wallets", operation: "updateOne", userId: String(userId), error: safeErr(err) });
    throw err;
  }
}

export async function createWallet(userId) {
  if (!cfg.WALLET_ENCRYPTION_SECRET) throw new Error("Wallet encryption is not configured yet.");
  const wallet = Wallet.createRandom();
  const encrypted = encryptSecret({ privateKey: wallet.privateKey, type: "generated" });
  return saveWallet(userId, wallet.address, encrypted, "generated");
}

export async function importWallet(userId, secret) {
  if (!cfg.WALLET_ENCRYPTION_SECRET) throw new Error("Wallet encryption is not configured yet.");
  const raw = String(secret || "").trim();
  if (!raw) throw new Error("Secret is empty.");
  let wallet;
  if (raw.split(/\s+/).length >= 12) wallet = Wallet.fromPhrase(raw);
  else wallet = new Wallet(raw);
  const encrypted = encryptSecret({ privateKey: wallet.privateKey, type: "imported" });
  return saveWallet(userId, wallet.address, encrypted, "imported");
}

export async function deleteWallet(userId) {
  const now = new Date();
  const wallets = await col("wallets");
  if (!wallets) {
    memoryWallets.delete(String(userId));
    return true;
  }
  try {
    await wallets.updateMany(
      { userId: String(userId), status: "active" },
      { $set: { status: "deleted", updatedAt: now }, $unset: { encryptedSecretPayload: "" } }
    );
    return true;
  } catch (err) {
    log.error("Wallet delete failed", { collection: "wallets", operation: "updateMany", userId: String(userId), error: safeErr(err) });
    throw err;
  }
}

export function shortAddress(address) {
  const s = String(address || "");
  return s ? `${s.slice(0, 6)}...${s.slice(-4)}` : "none";
}

